"python3 -c '
import re, subprocess
html = open("index.html").read()
strat = re.search(r"<script id=\"rampart-strategy\">(.*?)</script>", html, re.S).group(1)
sim = re.search(r"<script id=\"rampart-sim\">(.*?)</script>", html, re.S).group(1)
test = strat + "\n" + sim + """
const stratA = () => ({ plan(s) { const a = []; let g = s.gold; for (const sl of s.slots) if (!sl.turret && g >= 50) { a.push({ op: "build", slot: sl.slot, type: "bolt" }); g -= 50; } return a; } });
const rA = rampartSimulate(stratA, 42, 12020);
const stratB = () => ({ plan(s) { if (s.wave === 1) return [{op:"build",slot:3,type:"cannon"},{op:"build",slot:6,type:"frost"}]; if (s.wave === 3) return [{op:"upgrade",slot:3},{op:"build",slot:12,type:"flak"}]; if (s.wave === 6) return [{op:"build",slot:8,type:"lance"},{op:"sell",slot:6}]; return []; } });
const rB = rampartSimulate(stratB, 7, 12020);
const r42 = rampartSimulate(createStrategy, 42, 2020);
let sum = 0; for (let s = 1; s <= 20; s++) sum += rampartSimulate(createStrategy, s, 12020).score;
print("VectorA:", rA.score, rA.fallTick, rA.log.length, rA.hash);
print("VectorB:", rB.score, rB.fallTick, rB.log.length, rB.hash);
print("Seed42:", r42.score, r42.fallTick, r42.hash);
print("Mean20:", (sum/20).toFixed(2));
"""
p = subprocess.run(["/System/Library/Frameworks/JavaScriptCore.framework/Versions/Current/Helpers/jsc", "-e", test], capture_output=True, text=True)
print(p.stdout, p.stderr)
assert p.returncode == 0
' && ls -la"
